// 隔离共享候选：原玩家守卫、同候选权源和原Office账共同完成四项真实办理。
#include "political_successor_round_world.hpp"
#include "political_term_handover_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
// 新轮必须同具原首轮、原组织、完整生命与实交目录，不能靠空账暗开。
Status available(const WorldBundle& w){if(!w.catalog->political_successor_rounds||!w.political_successor_rounds||!w.catalog->political_successions||!w.political_successions||!w.politics_enabled()||!w.catalog->organization||!w.catalog->organization->enabled||!w.family_life_enabled()||!w.catalog->task_message_notices||!w.tasks.message_notices||!w.tasks.message_handoffs||!w.catalog->tasks||!w.catalog->common)return common_failure("PoliticalSuccessorRoundProfileRequired");
 // 空账也须核每项作者原辖区；此处不以当前失控否定先前合法历史。
 for(const auto& row:w.catalog->political_successions->policies.rows()){const auto& p=row.second;const auto* j=w.catalog->politics->jurisdictions.find(p.jurisdiction_id);if(!j||j->id!=p.jurisdiction_id||j->revision!=0||j->office_id!=p.leader_office_id||j->seat_place_id!=p.seat_place_id||j->political_organization_id!=p.organization_id||j->controlling_organization_id!=p.organization_id)return common_failure("PoliticalSuccessorRoundOriginalSeatRequired",p.id);}
 return common_success();}
// 复用原PoliticsEffects具体字段，空Done不能冒称对应本次真实继位source。
bool actual_result(const CommitResult& r,const StableId& source,const StableId& office){if(!r.ok||!r.details||!is_political_successor_round_command(r.kind))return false;const auto* e=std::get_if<PoliticsEffects>(&r.details->data);return e&&e->appointment_id.empty()&&e->fact_ids==std::vector<StableId>{source}&&e->receipt_ids==(office.empty()?std::vector<StableId>{}:std::vector<StableId>{office});}
// 先保原生命/占用/会面守卫，再限定真实当前受控本人。
Status player(const WorldBundle& w,const StableId& actor,const PoliticalSuccessorRoundCommand& c){auto guard=command_common_guard(w,actor,political_successor_round_command_kind(c));if(!guard.ok)return guard;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PoliticalSuccessorRoundPlayerCommandRequired");}
}
// 原权源和通知持者先构造，后续所有引用只借同一不移动的holder。
PoliticalSuccessorRoundWorldAccess::PoliticalSuccessorRoundWorldAccess(const WorldBundle& w,TaskMessageNoticeServices notices)
 :world_(w),military_(w.political_takeover_enabled()?std::optional<MilitaryAccess>{w.services.military_access()}:std::nullopt),
 occupations_(w.political_takeover_enabled()?std::optional<PoliticalSuccessionOccupationContext>{PoliticalSuccessionOccupationContext{w.political_takeover,*w.catalog->political_takeover,w.military,*w.catalog->military,*military_}}:std::nullopt),
 territory_{w.common,w.politics,*w.catalog->politics,occupations_?&*occupations_:nullptr},notices_(std::move(notices)),
 heads_{w.common,w.organization,*w.catalog->organization,*w.catalog->political_successions,w.political_successions->nominations,w.political_successions->accessions,w.catalog->political_head_handovers.get(),w.political_head_handovers?&*w.political_head_handovers:nullptr,political_term_handover_head_read_world(w)},
 nominations_{w.common,*w.catalog->common,w.organization,*w.catalog->organization,w.local_economy,w.services,heads_,*w.catalog->political_successor_rounds,*w.political_successor_rounds,w.family_death_read(),[this](const PoliticalSuccessionPolicy& policy,Integer tick,const StableId& boundary){return validate_political_successor_round_seat(territory_,policy,tick,boundary);},[&w](Integer tick,const StableId& boundary){return read_political_successor_round_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,boundary);}},
 sources_{nominations_,w.family_life,[this](const StableId& actor,const StableId& binding){const auto& w=world_;return read_delivered_task_death_notice(w.common,w.tasks,*w.catalog->tasks,*w.catalog->common,*w.catalog->task_message_notices,*w.tasks.message_notices,*w.tasks.message_handoffs,notices_.validate,actor,binding);}},context_{sources_,*w.political_successor_rounds,actual_result}{}
// 失败不返回半个读上下文；原已收文书服务必须实际可构造。
Outcome<std::unique_ptr<PoliticalSuccessorRoundWorldAccess>> PoliticalSuccessorRoundWorldAccess::create(const WorldBundle& w){auto valid=available(w);if(!valid.ok)return {false,{},valid.error};auto notices=make_task_message_notice_services(w);if(!notices.ok)return {false,{},notices.error};if(!notices.value)return {false,{},common_failure("PoliticalSuccessorRoundNoticeReadRequired").error};return {true,std::unique_ptr<PoliticalSuccessorRoundWorldAccess>{new PoliticalSuccessorRoundWorldAccess(w,std::move(*notices.value))},{}};}
// 仅枚举本人的真实实交观察索引，远方发信/尚未交付均不进入此候选列表。
PoliticalSuccessorRoundViewContext PoliticalSuccessorRoundWorldAccess::view()const{return {context_,[this](const StableId& actor)->Outcome<std::vector<StableId>>{const auto& w=world_;std::vector<StableId> ids;const auto found=w.tasks.message_handoffs->observed_by.find(actor);if(found==w.tasks.message_handoffs->observed_by.end())return {true,std::move(ids),{}};for(const auto& id:found->second){const auto* handoff=w.tasks.message_handoffs->receipts.find(id);if(!handoff)return {false,{},common_failure("TaskMessageHandoffObserverIndexMismatch",id).error};if(handoff->recipient_actor_id!=actor)continue;const auto binding=w.tasks.message_notices->task_to_binding.find(handoff->task_id);if(binding!=w.tasks.message_notices->task_to_binding.end())ids.push_back(binding->second);}return {true,std::move(ids),{}};}};}
// 初始化只在明确新profile下生成空独立账，不产生提名或补造首任Office。
Status initialize_political_successor_round_world_in_candidate(WorldBundle& w){if(!w.catalog->political_successor_rounds)return w.political_successor_rounds?common_failure("PoliticalSuccessorRoundProfileMismatch"):common_success();if(w.common.tick()!=0||w.political_successor_rounds)return common_failure("PoliticalSuccessorRoundInitialStateRequired");w.political_successor_rounds.emplace();return validate_political_successor_round_world(w);}
// 完整Family/Birth/Legacy/Task实交与军事控制先验之后，才核正式政治史和永久提交。
Status validate_political_successor_round_world(const WorldBundle& w){auto layout=validate_political_successor_round_layout(w.common,w.catalog->identity.module_versions,w.political_successor_rounds?&*w.political_successor_rounds:nullptr);if(!layout.ok)return layout;if(bool(w.catalog->political_successor_rounds)!=w.political_successor_rounds.has_value())return common_failure("PoliticalSuccessorRoundProfileMismatch");if(!w.catalog->political_successor_rounds)return common_success();auto read=PoliticalSuccessorRoundWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return validate_political_successor_rounds(read.value->context());}
// 每次预览重建同一候选读，报价不能缓存跨换职或控制切换的引用。
Outcome<PoliticalSuccessorRoundQuote> prepare_political_successor_round_world(const WorldBundle& w,const StableId& actor,const PoliticalSuccessorRoundCommand& c){auto valid=player(w,actor,c);if(!valid.ok)return {false,{},valid.error};auto read=PoliticalSuccessorRoundWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return preview_political_successor_round(read.value->context(),actor,c);}
// 原命令守卫后重新完整报价，只有正式就任由原Office账写一条变更。
Outcome<PoliticsEffects> commit_political_successor_round_world(WorldBundle& w,const StableId& actor,const PoliticalSuccessorRoundCommand& c,const PoliticalSuccessorRoundQuote& quote){auto valid=player(w,actor,c);if(!valid.ok)return {false,{},valid.error};auto read=PoliticalSuccessorRoundWorldAccess::create(w);if(!read.ok)return {false,{},read.error};auto result=apply_political_successor_round_in_candidate(w.common,w.organization,*w.political_successor_rounds,read.value->context(),actor,c,quote);if(!result.ok)return {false,{},result.error};return {true,{{},{result.value.source_fact_id},result.value.office_change_fact_id.empty()?std::vector<StableId>{}:std::vector<StableId>{result.value.office_change_fact_id}},{}};}
// 有限页面同步消费自持读口，返回数据不保留World或局部引用。
Outcome<BoundaryValue> query_political_successor_round_world(const WorldBundle& w,const StableId& place,Integer cursor){auto read=PoliticalSuccessorRoundWorldAccess::create(w);if(!read.ok)return {false,{},read.error};auto view=read.value->view();return query_political_successor_rounds(view,place,cursor);}
// 真结果分配并进入原cache/history后才绑定本次唯一新源。
Status bind_political_successor_round_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& result){if(!w.political_successor_rounds||!w.catalog->political_successor_rounds||source.empty()||!is_political_successor_round_command(result.kind))return common_failure("PoliticalSuccessorRoundNewSourceRequired");return bind_political_successor_round_player_result(w.common,*w.political_successor_rounds,source,actor,request,result,actual_result);}
}
